function normalizeResultTemplateFont(value: string): ApprovedResultFont {
  return APPROVED_RESULT_FONTS.includes(value as ApprovedResultFont) ? value as ApprovedResultFont : DEFAULT_RESULT_TEMPLATE_LAYOUT.fontFamily;
}

export async function listResultTemplateLayouts() {
  const db = await getDb();
  const rows = db ? await db.select().from(resultTemplateLayouts) : [];
  const bySection = new Map(rows.map(row => [row.section, row]));
  return RESULT_TEMPLATE_SECTIONS.map(section => {
    const row = bySection.get(section);
    return row ? { ...row, fontFamily: normalizeResultTemplateFont(row.fontFamily) } : { id: 0, section, ...DEFAULT_RESULT_TEMPLATE_LAYOUT, editorConfig: null, updatedBy: null, createdAt: "", updatedAt: "" };
  });
}

export async function updateResultTemplateEditor(section: "Nursery" | "Primary" | "Junior" | "Senior", editorConfig: string, updatedBy: number) {
  const db = await getDb(); if (!db) throw new Error("Database unavailable");
  const existing = (await db.select({ id: resultTemplateLayouts.id }).from(resultTemplateLayouts).where(eq(resultTemplateLayouts.section, section)).limit(1))[0];
  if (existing) await db.update(resultTemplateLayouts).set({ editorConfig, updatedBy, updatedAt: new Date() }).where(eq(resultTemplateLayouts.id, existing.id));
  else await db.insert(resultTemplateLayouts).values({ section, editorConfig, updatedBy });
  return (await db.select().from(resultTemplateLayouts).where(eq(resultTemplateLayouts.section, section)).limit(1))[0];
}


