export async function updateStaffAccountPhoto(id: number, input: { profileImageUrl?: string | null; profileImageKey?: string | null }, changedBy?: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const existing = (await db.select({ profileImageUrl: users.profileImageUrl }).from(users).where(and(eq(users.id, id), eq(users.loginMethod, "local"), inArray(users.role, ["admin", "principal", "teacher", "accountant"]))).limit(1))[0]; if (!existing) throw new Error("Staff account not found"); await db.update(users).set({ ...input, updatedAt: new Date() }).where(and(eq(users.id, id), eq(users.loginMethod, "local"), inArray(users.role, ["admin", "principal", "teacher", "accountant"]))); if (changedBy) await db.insert(photoAuditLogs).values({ targetType: "staff", targetId: id, action: "replace", previousImageUrl: existing.profileImageUrl ?? null, newImageUrl: input.profileImageUrl ?? null, changedBy }); const result = await db.select(safeAccountFields).from(users).where(eq(users.id, id)).limit(1); return result[0]; }
export async function removeStaffAccountPhoto(id: number, changedBy: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const existing = (await db.select({ profileImageUrl: users.profileImageUrl }).from(users).where(and(eq(users.id, id), eq(users.loginMethod, "local"), inArray(users.role, ["admin", "principal", "teacher", "accountant"]))).limit(1))[0]; if (!existing) throw new Error("Staff account not found"); await db.update(users).set({ profileImageUrl: null, profileImageKey: null, updatedAt: new Date() }).where(eq(users.id, id)); await db.insert(photoAuditLogs).values({ targetType: "staff", targetId: id, action: "remove", previousImageUrl: existing.profileImageUrl ?? null, newImageUrl: null, changedBy }); return { id, removed: true as const }; }
