export function subjectLoginSlug(name: string) { return name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 48) || "subject"; }
export function subjectAccountUsername(subjectId: number) { return `AFS-${subjectId}`; }
export function subjectInitialPassword(subjectId: number) { return `AFS-${String(subjectId).padStart(4, "0")}-SUBJECT`; }
export function randomSubjectPassword() { let password = ""; while (password.length < 10) password += randomBytes(12).toString("base64url").replace(/[^a-zA-Z0-9]/g, ""); return password.slice(0, 10).toUpperCase(); }
export async function syncSubjectAccounts() { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const activeSubjects = await db.select().from(subjects).where(eq(subjects.status, "active")).orderBy(asc(subjects.name)); const existingRows = await db.select({ account: subjectAccounts, userId: users.id, username: users.username }).from(subjectAccounts).innerJoin(users, eq(subjectAccounts.userId, users.id)); const existingBySubject = new Map(existingRows.map(row => [row.account.subjectId, row])); const accounts = []; for (const subject of activeSubjects) { const username = subjectAccountUsername(subject.id); const existing = existingBySubject.get(subject.id); const initialPassword = existing?.account.initialPassword && !existing.account.initialPassword.endsWith("-SUBJECT") ? existing.account.initialPassword : randomSubjectPassword(); const credentialChanged = !existing || existing.account.username !== username || existing.account.initialPassword !== initialPassword; let userId = existing?.userId; if (!userId) { await db.insert(users).values({ openId: `local:subject:${subject.id}`, name: `Subject Account — ${subject.name}`, username, passwordHash: hashPassword(initialPassword), loginMethod: "local", role: "teacher", linkedSubjectId: subject.id, mustChangePassword: true, accountStatus: "active" }); userId = (await db.select({ id: users.id }).from(users).where(eq(users.username, username)).limit(1))[0]?.id; } if (!userId) continue; const userUpdate: Record<string, unknown> = { name: `Subject Account — ${subject.name}`, role: "teacher", linkedSubjectId: subject.id, accountStatus: "active" }; if (credentialChanged) { userUpdate.username = username; userUpdate.passwordHash = hashPassword(initialPassword); userUpdate.mustChangePassword = true; } await db.update(users).set(userUpdate).where(eq(users.id, userId)); if (existing) await db.update(subjectAccounts).set({ userId, username, initialPassword, status: "active", updatedAt: new Date() }).where(eq(subjectAccounts.subjectId, subject.id)); else await db.insert(subjectAccounts).values({ subjectId: subject.id, userId, username, initialPassword, status: "active" }); accounts.push({ subjectId: subject.id, subjectName: subject.name, arabicName: subject.arabicName, username, initialPassword, userId }); } const actualAssignments = await db.select({ subjectAccountId: subjectAccounts.id, classId: academyClasses.id }).from(subjectAccounts).innerJoin(subjects, eq(subjectAccounts.subjectId, subjects.id)).innerJoin(classSubjects, eq(classSubjects.name, subjects.name)).innerJoin(academyClasses, eq(classSubjects.classId, academyClasses.id)).where(and(eq(subjectAccounts.status, "active"), eq(classSubjects.status, "active"), eq(academyClasses.status, "active"))); await db.delete(subjectAccountClasses); if (actualAssignments.length) await db.insert(subjectAccountClasses).values(actualAssignments.map(item => ({ subjectAccountId: item.subjectAccountId, classId: item.classId }))); return accounts; }
export async function listSubjectAccounts() { const db = await getDb(); if (!db) return []; const rows = await db.select({ account: subjectAccounts, subjectName: subjects.name, arabicName: subjects.arabicName, accountStatus: users.accountStatus }).from(subjectAccounts).innerJoin(subjects, eq(subjectAccounts.subjectId, subjects.id)).innerJoin(users, eq(subjectAccounts.userId, users.id)).where(eq(subjectAccounts.status, "active")).orderBy(asc(subjects.name)); const assignments = await db.select({ accountId: subjectAccountClasses.subjectAccountId, classId: academyClasses.id, className: academyClasses.name }).from(subjectAccountClasses).innerJoin(academyClasses, eq(subjectAccountClasses.classId, academyClasses.id)).orderBy(asc(academyClasses.name)); const byAccount = new Map<number, { classId: number; className: string }[]>(); for (const assignment of assignments) { const current = byAccount.get(assignment.accountId) ?? []; current.push({ classId: assignment.classId, className: assignment.className }); byAccount.set(assignment.accountId, current); } return rows.map(row => ({ ...row, assignedClasses: byAccount.get(row.account.id) ?? [] })); }
