export async function setSubjectAccountClasses(subjectAccountId: number, classIds: number[]) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.delete(subjectAccountClasses).where(eq(subjectAccountClasses.subjectAccountId, subjectAccountId)); if (classIds.length) await db.insert(subjectAccountClasses).values(classIds.map(classId => ({ subjectAccountId, classId }))); return listSubjectAccountAssignments(); }
export async function resetSubjectAccountPassword(subjectAccountId: number) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const account = (await db.select().from(subjectAccounts).where(eq(subjectAccounts.id, subjectAccountId)).limit(1))[0]; if (!account) return undefined; await db.update(users).set({ passwordHash: hashPassword(account.initialPassword), mustChangePassword: true, accountStatus: "active", updatedAt: new Date() }).where(eq(users.id, account.userId)); return { subjectAccountId, username: account.username, initialPassword: account.initialPassword }; }
export async function isTeacherAssignedToSubject(teacherId: number, className: string, subjectName: string) { const db = await getDb(); if (!db) return false; const account = (await db.select({ linkedSubjectId: users.linkedSubjectId }).from(users).where(eq(users.id, teacherId)).limit(1))[0]; const linkedSubject = account?.linkedSubjectId ? (await db.select({ id: subjects.id }).from(subjects).where(and(eq(subjects.id, account.linkedSubjectId), eq(subjects.name, subjectName))).limit(1))[0] : undefined; if (linkedSubject) { const subjectAccount = (await db.select({ id: subjectAccounts.id }).from(subjectAccounts).where(and(eq(subjectAccounts.userId, teacherId), eq(subjectAccounts.subjectId, linkedSubject.id), eq(subjectAccounts.status, "active"))).limit(1))[0]; if (!subjectAccount) return false; const allowedClass = (await db.select({ id: subjectAccountClasses.id, classId: academyClasses.id }).from(subjectAccountClasses).innerJoin(academyClasses, eq(subjectAccountClasses.classId, academyClasses.id)).where(and(eq(subjectAccountClasses.subjectAccountId, subjectAccount.id), eq(academyClasses.name, className), eq(academyClasses.status, "active"))).limit(1))[0]; if (!allowedClass) return false; const activeSubjectAssignment = (await db.select({ id: classSubjects.id }).from(classSubjects).where(and(eq(classSubjects.classId, allowedClass.classId), eq(classSubjects.name, subjectName), eq(classSubjects.status, "active"))).limit(1))[0]; return Boolean(activeSubjectAssignment); } const rows = await db.select({ id: classSubjects.id }).from(classSubjects).innerJoin(academyClasses, eq(classSubjects.classId, academyClasses.id)).where(and(eq(academyClasses.name, className), eq(classSubjects.name, subjectName), eq(classSubjects.status, "active"), eq(classSubjects.teacherId, teacherId))).limit(1); return Boolean(rows[0]); }
