export async function createSubject(input: Pick<InsertSubject, "name" | "arabicName">) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const name = input.name.trim(); const arabicName = input.arabicName.trim(); await db.insert(subjects).values({ name, arabicName, status: "active" }); return (await db.select().from(subjects).where(eq(subjects.name, name)).limit(1))[0]; }
export async function updateSubject(id: number, input: Pick<InsertSubject, "name" | "arabicName">) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const existing = await db.select().from(subjects).where(eq(subjects.id, id)).limit(1); const previousName = existing[0]?.name; await db.update(subjects).set({ name: input.name.trim(), arabicName: input.arabicName.trim(), updatedAt: new Date() }).where(eq(subjects.id, id)); if (previousName) await db.update(classSubjects).set({ name: input.name.trim(), arabicName: input.arabicName.trim(), updatedAt: new Date() }).where(eq(classSubjects.name, previousName)); return (await db.select().from(subjects).where(eq(subjects.id, id)).limit(1))[0]; }
