export async function createExamCard(input: Omit<InsertExamCard, "id" | "issuedAt" | "updatedAt">) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const existing = (await db.select({ id: examCards.id }).from(examCards).where(and(eq(examCards.studentId, input.studentId), eq(examCards.session, input.session), eq(examCards.term, input.term), eq(examCards.className, input.className), eq(examCards.examinationTitle, input.examinationTitle), eq(examCards.status, "issued"))).orderBy(desc(examCards.issuedAt)).limit(1))[0]; const nextValues = { ...input, visibilityStatus: "approved" as const, approvedBy: null, approvedAt: null, updatedAt: new Date() }; if (existing) { await db.update(examCards).set(nextValues).where(eq(examCards.id, existing.id)); return (await db.select().from(examCards).where(eq(examCards.id, existing.id)).limit(1))[0]; } await db.insert(examCards).values(nextValues); return (await db.select().from(examCards).where(and(eq(examCards.studentId, input.studentId), eq(examCards.session, input.session), eq(examCards.term, input.term), eq(examCards.className, input.className), eq(examCards.examinationTitle, input.examinationTitle))).orderBy(desc(examCards.issuedAt)).limit(1))[0]; }
function sectionMatchesExamCardScope(requested: string, actual: string) { const wanted = requested.trim().toLowerCase(); const value = actual.trim().toLowerCase(); return wanted === "junior" ? value === "junior" || value === "jss" : wanted === "senior" ? value === "senior" || value === "sss" : value === wanted; }
export async function bulkIssueExamCards(input: { session: string; term: string; className?: string; section?: string; examinationTitle: string; examinationDate: Date | null; venue: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); if (!input.className && !input.section) throw new Error("Choose a class or section to issue examination cards"); const classConditions = [eq(academyClasses.status, "active")]; if (input.className) classConditions.push(eq(academyClasses.name, input.className)); const classRows = await db.select({ id: academyClasses.id, name: academyClasses.name, section: academyClasses.section }).from(academyClasses).where(and(...classConditions)); const targets = input.section ? classRows.filter(row => sectionMatchesExamCardScope(input.section as string, row.section)) : classRows; if (!targets.length) return { classes: 0, students: 0, created: 0, updated: 0, classesWithoutSubjects: [] as string[], cardIds: [] as number[] }; const cardsToIssue: Array<InsertExamCard> = []; const classesWithoutSubjects: string[] = []; for (const target of targets) { const roster = await listSessionRoster(input.session, target.name); const subjectRows = await db.select({ name: classSubjects.name, arabicName: classSubjects.arabicName }).from(classSubjects).where(and(eq(classSubjects.classId, target.id), eq(classSubjects.status, "active"))).orderBy(asc(classSubjects.displayOrder), asc(classSubjects.name)); if (!subjectRows.length) classesWithoutSubjects.push(target.name); const subjectsJson = JSON.stringify(subjectRows.map(subject => ({ name: subject.name, arabicName: subject.arabicName, date: "", time: "" }))); const timetableJson = JSON.stringify(subjectRows.map(subject => ({ subject: subject.name, date: "", time: "" }))); for (const student of roster) cardsToIssue.push({ studentId: student.id, session: input.session, term: input.term, className: target.name, examinationTitle: input.examinationTitle, examinationDate: input.examinationDate, venue: input.venue, subjectsJson, timetableJson, status: "issued", visibilityStatus: "approved", approvedBy: null, approvedAt: null }); } if (!cardsToIssue.length) return { classes: targets.length, students: 0, created: 0, updated: 0, classesWithoutSubjects, cardIds: [] as number[] }; const existing = await db.select({ id: examCards.id, studentId: examCards.studentId, className: examCards.className }).from(examCards).where(and(eq(examCards.session, input.session), eq(examCards.term, input.term), eq(examCards.examinationTitle, input.examinationTitle), inArray(examCards.studentId, cardsToIssue.map(card => card.studentId)))); const existingByKey = new Map(existing.map(card => [`${card.studentId}::${card.className}`, card])); const createdRows = cardsToIssue.filter(card => !existingByKey.has(`${card.studentId}::${card.className}`)); const updatedRows = cardsToIssue.filter(card => existingByKey.has(`${card.studentId}::${card.className}`)); await db.transaction(async tx => { for (const card of updatedRows) { const current = existingByKey.get(`${card.studentId}::${card.className}`); if (current) await tx.update(examCards).set({ session: card.session, term: card.term, className: card.className, examinationTitle: card.examinationTitle, examinationDate: card.examinationDate, venue: card.venue, subjectsJson: card.subjectsJson, timetableJson: card.timetableJson, status: "issued", visibilityStatus: "approved", approvedBy: null, approvedAt: null, updatedAt: new Date() }).where(eq(examCards.id, current.id)); } if (createdRows.length) await tx.insert(examCards).values(createdRows); }); const refreshed = await db.select({ id: examCards.id }).from(examCards).where(and(eq(examCards.session, input.session), eq(examCards.term, input.term), eq(examCards.examinationTitle, input.examinationTitle), eq(examCards.status, "issued"), inArray(examCards.studentId, cardsToIssue.map(card => card.studentId)))); return { classes: targets.length, students: cardsToIssue.length, created: createdRows.length, updated: updatedRows.length, classesWithoutSubjects, cardIds: refreshed.map(row => row.id) }; }
export async function listExamCards(filters: { session?: string; term?: string; className?: string; studentId?: number; approvedOnly?: boolean; studentVisible?: boolean; visibilityStatus?: "pending" | "approved" | "hidden" } = {}) { const db = await getDb(); if (!db) return []; const conditions = []; if (filters.session) conditions.push(eq(examCards.session, filters.session)); if (filters.term) conditions.push(eq(examCards.term, filters.term)); if (filters.className) conditions.push(eq(examCards.className, filters.className)); if (filters.studentId) conditions.push(eq(examCards.studentId, filters.studentId)); if (filters.studentVisible) conditions.push(or(eq(examCards.visibilityStatus, "pending"), eq(examCards.visibilityStatus, "approved"))); if (filters.approvedOnly) conditions.push(eq(examCards.visibilityStatus, "approved")); if (filters.visibilityStatus) conditions.push(eq(examCards.visibilityStatus, filters.visibilityStatus)); const rows = await db.select({ card: examCards, student: students }).from(examCards).innerJoin(students, eq(examCards.studentId, students.id)).where(conditions.length ? and(...conditions) : undefined).orderBy(desc(examCards.issuedAt)); if (!rows.length) return rows; const classNames = Array.from(new Set(rows.map(row => row.card.className))); const classRows = await db.select({ id: academyClasses.id, name: academyClasses.name }).from(academyClasses).where(and(inArray(academyClasses.name, classNames), eq(academyClasses.status, "active"))); const classIds = classRows.map(row => row.id); if (!classIds.length) return rows; const liveSubjects = await db.select({ classId: classSubjects.classId, name: classSubjects.name, arabicName: classSubjects.arabicName }).from(classSubjects).where(and(inArray(classSubjects.classId, classIds), eq(classSubjects.status, "active"))).orderBy(asc(classSubjects.displayOrder), asc(classSubjects.name)); const classNameById = new Map(classRows.map(row => [row.id, row.name])); const subjectsByClass = new Map<string, typeof liveSubjects>(); for (const subject of liveSubjects) { const className = classNameById.get(subject.classId); if (!className) continue; const current = subjectsByClass.get(className) ?? []; current.push(subject); subjectsByClass.set(className, current); } return rows.map(row => { const activeSubjects = subjectsByClass.get(row.card.className); if (!activeSubjects) return row; let persistedSubjects: any[] = []; let persistedTimetable: any[] = []; try { persistedSubjects = JSON.parse(row.card.subjectsJson || "[]"); } catch {} try { persistedTimetable = JSON.parse(row.card.timetableJson || "[]"); } catch {} const persistedByName = new Map(persistedSubjects.filter(item => item?.name).map(item => [String(item.name).trim().toLowerCase(), item])); const timetableByName = new Map(persistedTimetable.filter(item => item?.subject).map(item => [String(item.subject).trim().toLowerCase(), item])); const subjectsJson = activeSubjects.map(subject => { const key = subject.name.trim().toLowerCase(); const previous = persistedByName.get(key) ?? {}; const timetable = timetableByName.get(key) ?? {}; return { name: subject.name, arabicName: subject.arabicName, date: previous.date ?? timetable.date ?? "", time: previous.time ?? timetable.time ?? "" }; }); const timetableJson = subjectsJson.map(subject => ({ subject: subject.name, date: subject.date, time: subject.time })); return { ...row, card: { ...row.card, subjectsJson: JSON.stringify(subjectsJson), timetableJson: JSON.stringify(timetableJson) } }; }); }
