export async function promoteStudents(input: { studentIds: number[]; fromClassName: string; toClassName: string; fromSession?: string; toSession?: string; promotedBy: number }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); if (!input.studentIds.length) throw new Error("Select at least one student to promote"); if (input.fromClassName === input.toClassName && input.fromSession === input.toSession) throw new Error("Choose a different target class or session"); const target = (await db.select({ id: academyClasses.id }).from(academyClasses).where(and(eq(academyClasses.name, input.toClassName), eq(academyClasses.status, "active"))).limit(1))[0]; if (!target) throw new Error("Target class is not active"); const selected = await db.select({ id: students.id, className: students.className }).from(students).where(and(inArray(students.id, input.studentIds), eq(students.className, input.fromClassName), eq(students.status, "active"))); if (selected.length !== input.studentIds.length) throw new Error("Some selected students are no longer in the source class"); await db.transaction(async tx => { await tx.insert(studentPromotions).values(selected.map(student => ({ studentId: student.id, fromClassName: input.fromClassName, toClassName: input.toClassName, fromSession: input.fromSession ?? null, toSession: input.toSession ?? null, promotedBy: input.promotedBy }))); if (input.fromSession) await tx.insert(studentEnrollments).values(selected.map(student => ({ studentId: student.id, session: input.fromSession as string, className: input.fromClassName, source: "promotion" as const }))).onDuplicateKeyUpdate({ set: { className: input.fromClassName, source: "promotion" as const, updatedAt: new Date() } }); if (input.toSession) await tx.insert(studentEnrollments).values(selected.map(student => ({ studentId: student.id, session: input.toSession as string, className: input.toClassName, source: "promotion" as const }))).onDuplicateKeyUpdate({ set: { className: input.toClassName, source: "promotion" as const, updatedAt: new Date() } }); await tx.update(students).set({ className: input.toClassName, updatedAt: new Date() }).where(inArray(students.id, input.studentIds)); }); return { migrated: selected.length, fromClassName: input.fromClassName, toClassName: input.toClassName, fromSession: input.fromSession ?? null, toSession: input.toSession ?? null }; }
export async function listStudentPromotions() { const db = await getDb(); if (!db) return []; return db.select({ promotion: studentPromotions, studentName: students.name, admissionNo: students.admissionNo }).from(studentPromotions).leftJoin(students, eq(studentPromotions.studentId, students.id)).orderBy(desc(studentPromotions.promotedAt)).limit(100); }
export async function rollbackStudentPromotion(input: { promotionId: number; rolledBackBy: number }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const promotion = (await db.select().from(studentPromotions).where(eq(studentPromotions.id, input.promotionId)).limit(1))[0]; if (!promotion) throw new Error("Promotion record not found"); if (promotion.rolledBackAt) throw new Error("This promotion has already been rolled back"); const student = (await db.select({ id: students.id, className: students.className, status: students.status }).from(students).where(eq(students.id, promotion.studentId)).limit(1))[0]; if (!student || student.className !== promotion.toClassName) throw new Error("This promotion cannot be rolled back because the student is no longer in the promoted class"); await db.transaction(async tx => { await tx.update(students).set({ className: promotion.fromClassName, updatedAt: new Date() }).where(eq(students.id, promotion.studentId)); await tx.update(studentPromotions).set({ rolledBackBy: input.rolledBackBy, rolledBackAt: new Date() }).where(eq(studentPromotions.id, input.promotionId)); }); return { promotionId: input.promotionId, studentId: promotion.studentId, restoredClassName: promotion.fromClassName }; }
export async function graduateStudents(input: { studentIds: number[]; finalClassName: string; graduatedBy: number }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); if (!input.studentIds.length) throw new Error("Select at least one final-year student"); const selected = await db.select({ id: students.id, name: students.name, admissionNo: students.admissionNo, className: students.className }).from(students).where(and(inArray(students.id, input.studentIds), eq(students.className, input.finalClassName), eq(students.status, "active"))); if (selected.length !== input.studentIds.length) throw new Error("Some selected students are no longer active in the final class"); const existing = await db.select({ studentId: alumni.studentId }).from(alumni).where(inArray(alumni.studentId, input.studentIds)); if (existing.length) throw new Error("One or more selected students are already in the alumni register"); await db.transaction(async tx => { await tx.insert(alumni).values(selected.map(student => ({ studentId: student.id, name: student.name, admissionNo: student.admissionNo, finalClassName: student.className, graduatedBy: input.graduatedBy }))); await tx.update(students).set({ status: "inactive", updatedAt: new Date() }).where(inArray(students.id, input.studentIds)); }); return { graduated: selected.length, finalClassName: input.finalClassName }; }
export async function listAlumni() { const db = await getDb(); if (!db) return []; return db.select().from(alumni).orderBy(desc(alumni.graduatedAt)).limit(500); }


export async function pageStudents(filters: { search?: string; className?: string; gender?: "male" | "female" | "unspecified"; page: number; pageSize: number }) { const db = await getDb(); if (!db) return { rows: [], total: 0, page: filters.page, pageSize: filters.pageSize, totalPages: 0 }; const conditions = []; if (filters.search) conditions.push(like(students.name, `%${filters.search}%`)); if (filters.className && filters.className !== "All classes") conditions.push(eq(students.className, filters.className)); if (filters.gender) conditions.push(eq(students.gender, filters.gender)); const where = conditions.length ? and(...conditions) : undefined; const [rows, totals] = await Promise.all([db.select().from(students).where(where).orderBy(asc(students.name)).limit(filters.pageSize).offset((filters.page - 1) * filters.pageSize), db.select({ value: count() }).from(students).where(where)]); const total = Number(totals[0]?.value ?? 0); return { rows, total, page: filters.page, pageSize: filters.pageSize, totalPages: Math.ceil(total / filters.pageSize) }; }
export async function getStudentProfile(id: number, options: { publishedResultsOnly?: boolean } = {}) { const db = await getDb(); if (!db) return null; const student = (await db.select().from(students).where(eq(students.id, id)).limit(1))[0]; if (!student) return null; const resultWhere = options.publishedResultsOnly ? and(eq(resultEntries.studentId, id), eq(resultEntries.status, "published")) : eq(resultEntries.studentId, id); const [results, paymentsForStudent, invoicesForStudent, attendance] = await Promise.all([db.select().from(resultEntries).where(resultWhere).orderBy(desc(resultEntries.updatedAt)), db.select().from(payments).where(eq(payments.studentId, id)).orderBy(desc(payments.createdAt)), db.select().from(invoices).where(eq(invoices.studentId, id)).orderBy(desc(invoices.createdAt)), db.select().from(attendanceRecords).where(eq(attendanceRecords.studentId, id)).orderBy(desc(attendanceRecords.attendanceDate))]); return { student, results, payments: paymentsForStudent, invoices: invoicesForStudent, attendance }; }
export async function getStudentCaSheet(filters: { search?: string; className?: string } = {}) { const db = await getDb(); if (!db) return []; const conditions = []; if (filters.search) conditions.push(like(students.name, `%${filters.search}%`)); if (filters.className && filters.className !== "All classes") conditions.push(eq(students.className, filters.className)); const studentRows = await db.select().from(students).where(conditions.length ? and(...conditions) : undefined).orderBy(asc(students.name)); const resultRows = await db.select().from(resultEntries).orderBy(desc(resultEntries.updatedAt)); const latest = new Map<number, typeof resultRows[number]>(); for (const result of resultRows) if (!latest.has(result.studentId)) latest.set(result.studentId, result); return studentRows.map(student => { const result = latest.get(student.id); return { student, firstCa: result?.firstCa ?? 0, secondCa: result?.secondCa ?? 0, thirdCa: result?.thirdCa ?? 0, exam: result?.examScore ?? 0, updatedAt: result?.updatedAt ?? null }; }); }
type Database = NonNullable<Awaited<ReturnType<typeof getDb>>>;

async function generateStudentAdmissionNumber(db: Database, className: string) {
  const section = getStudentSectionPrefix(className);
  const prefix = `2026/AFSAL/${section}/`;
  const existing = await db.select({ admissionNo: students.admissionNo }).from(students).where(like(students.admissionNo, `${prefix}%`));
  const used = new Set(existing.map(row => row.admissionNo));
  for (let sequence = 1; sequence <= 999; sequence += 1) {
    const candidate = formatStudentAdmissionNumber(className, sequence);
    if (!used.has(candidate)) return candidate;
  }
  throw new Error(`No available admission-number sequence remains for ${section}`);
}

async function provisionStudentAccount(db: Database, student: { id: number; name: string; admissionNo: string; status: "active" | "pending" | "inactive" }, resetPassword = false) {
  const linked = await db.select().from(users).where(and(eq(users.linkedStudentId, student.id), eq(users.loginMethod, "local"))).limit(1);
  const byUsername = await db.select().from(users).where(eq(users.username, student.admissionNo)).limit(1);
  const account = linked[0] ?? (byUsername[0]?.role === "student" ? byUsername[0] : undefined);
  const accountStatus = student.status === "inactive" ? "inactive" : "active";
  if (account) {
    await db.update(users).set({ name: student.name, username: student.admissionNo, linkedStudentId: student.id, role: "student", loginMethod: "local", accountStatus, ...(resetPassword ? { passwordHash: hashPassword(INITIAL_STUDENT_PASSWORD), mustChangePassword: true } : {}), updatedAt: new Date() }).where(eq(users.id, account.id));
    return account.id;
  }
  await db.insert(users).values({ openId: `local:student:${student.id}`, name: student.name, username: student.admissionNo, passwordHash: hashPassword(INITIAL_STUDENT_PASSWORD), loginMethod: "local", role: "student", accountStatus, mustChangePassword: true, linkedStudentId: student.id });
  const created = await db.select({ id: users.id }).from(users).where(eq(users.username, student.admissionNo)).limit(1);
  return created[0]?.id;
}
export async function resetStudentPassword(studentId: number) {
  const db = await getDb(); if (!db) throw new Error("Database unavailable");
  const student = (await db.select().from(students).where(eq(students.id, studentId)).limit(1))[0];
  if (!student) throw new Error("Student not found");
  await provisionStudentAccount(db, student, true);
  return { success: true as const, username: student.admissionNo, initialPassword: INITIAL_STUDENT_PASSWORD, mustChangePassword: true as const };
}
export async function createStudentAccounts() {
  const db = await getDb(); if (!db) return { synchronized: 0 };
  const roster = await db.select({ id: students.id, name: students.name, admissionNo: students.admissionNo, status: students.status }).from(students);
  if (!roster.length) return { synchronized: 0 };
  const initialPasswordHash = hashPassword(INITIAL_STUDENT_PASSWORD);
  await db.insert(users).values(roster.map(student => ({ openId: `local:student:${student.id}`, name: student.name, username: student.admissionNo, passwordHash: initialPasswordHash, loginMethod: "local", role: "student" as const, accountStatus: student.status === "inactive" ? "inactive" as const : "active" as const, linkedStudentId: student.id }))).onDuplicateKeyUpdate({ set: { name: sql.raw("VALUES(name)"), username: sql.raw("VALUES(username)"), loginMethod: sql.raw("VALUES(loginMethod)"), role: sql.raw("VALUES(role)"), accountStatus: sql.raw("VALUES(accountStatus)"), linkedStudentId: sql.raw("VALUES(linkedStudentId)") } });
  return { synchronized: roster.length };
}

async function assertActiveClassExists(db: Awaited<ReturnType<typeof getDb>>, className: string) {
  if (!db) throw new Error("Database unavailable");
  const classRow = await db.select({ id: academyClasses.id }).from(academyClasses).where(and(eq(academyClasses.name, className.trim()), eq(academyClasses.status, "active"))).limit(1);
  if (!classRow[0]) throw new Error("Selected class does not exist or is inactive");
}

async function syncNewStudentEnrollments(db: Database, student: Pick<InsertStudent, "className"> & { id: number }, source: "manual" | "import") {
  const activeSessions = await db.select({ name: academicSessions.name }).from(academicSessions).where(eq(academicSessions.status, "active"));
  if (!activeSessions.length) return;
  await db.insert(studentEnrollments).values(activeSessions.map(session => ({ studentId: student.id, session: session.name, className: student.className, source }))).onDuplicateKeyUpdate({ set: { className: student.className, source, updatedAt: new Date() } });
}
export async function createStudent(input: Omit<InsertStudent, "admissionNo"> & { admissionNo?: string }, source: "manual" | "import" = "manual") {
  const db = await getDb(); if (!db) throw new Error("Database unavailable");
  await assertActiveClassExists(db, input.className);
  const admissionNo = await generateStudentAdmissionNumber(db, input.className);
  await db.insert(students).values({ ...input, admissionNo });
  const created = await db.select().from(students).where(eq(students.admissionNo, admissionNo)).limit(1);
  if (!created[0]) throw new Error("Student could not be created");
  await provisionStudentAccount(db, created[0], true);
  await syncNewStudentEnrollments(db, created[0], source);
  return created[0];
}
