export async function updateStudent(id: number, input: Partial<InsertStudent>) {
  const db = await getDb(); if (!db) throw new Error("Database unavailable");
  const existing = await db.select().from(students).where(eq(students.id, id)).limit(1);
  if (!existing[0]) throw new Error("Student not found");
  if (input.className) await assertActiveClassExists(db, input.className);
  const admissionNo = input.className && input.className !== existing[0].className ? await generateStudentAdmissionNumber(db, input.className) : existing[0].admissionNo;
  await db.update(students).set({ ...input, admissionNo, updatedAt: new Date() }).where(eq(students.id, id));
  const updated = await db.select().from(students).where(eq(students.id, id)).limit(1);
  if (updated[0]) await provisionStudentAccount(db, updated[0], false);
  return updated[0];
}
async function cleanupStudentRecords(db: Database, studentIds: number[]) {
  const ids = Array.from(new Set(studentIds.filter(id => Number.isInteger(id) && id > 0)));
  if (!ids.length) return 0;
  const existing = await db.select({ id: students.id }).from(students).where(inArray(students.id, ids));
  const existingIds = existing.map(student => student.id);
  if (!existingIds.length) return 0;
  return db.transaction(async tx => {
    const attempts = await tx.select({ id: jambAttempts.id }).from(jambAttempts).where(inArray(jambAttempts.studentId, existingIds));
    const attemptIds = attempts.map(attempt => attempt.id);
    if (attemptIds.length) {
      await tx.delete(jambAnswers).where(inArray(jambAnswers.attemptId, attemptIds));
      await tx.delete(jambLiveSessions).where(inArray(jambLiveSessions.attemptId, attemptIds));
    }
    await tx.delete(jambMonitoringEvents).where(inArray(jambMonitoringEvents.studentId, existingIds));
    await tx.delete(jambRecordings).where(inArray(jambRecordings.studentId, existingIds));
    await tx.delete(jambAttempts).where(inArray(jambAttempts.studentId, existingIds));
    await tx.delete(assignmentSubmissions).where(inArray(assignmentSubmissions.studentId, existingIds));
    await tx.delete(resultEntries).where(inArray(resultEntries.studentId, existingIds));
    await tx.delete(termlyReports).where(inArray(termlyReports.studentId, existingIds));
    await tx.delete(attendanceRecords).where(inArray(attendanceRecords.studentId, existingIds));
    await tx.delete(payments).where(inArray(payments.studentId, existingIds));
    await tx.delete(invoices).where(inArray(invoices.studentId, existingIds));
    await tx.delete(examCards).where(inArray(examCards.studentId, existingIds));
    await tx.delete(studentEnrollments).where(inArray(studentEnrollments.studentId, existingIds));
    await tx.delete(studentPromotions).where(inArray(studentPromotions.studentId, existingIds));
    await tx.delete(alumni).where(inArray(alumni.studentId, existingIds));
    await tx.delete(photoAuditLogs).where(and(eq(photoAuditLogs.targetType, "student"), inArray(photoAuditLogs.targetId, existingIds)));
    await tx.delete(users).where(and(inArray(users.linkedStudentId, existingIds), eq(users.role, "student")));
    await tx.update(users).set({ linkedStudentId: null, updatedAt: new Date() }).where(inArray(users.linkedStudentId, existingIds));
    const result = await tx.delete(students).where(inArray(students.id, existingIds));
    return Number(result[0]?.affectedRows ?? existingIds.length);
  });
}
