export async function createAssignmentSubmission(input: { assignmentId: number; studentId: number; submissionText?: string; submissionUrl?: string; submissionKey?: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); await db.insert(assignmentSubmissions).values(input); const result = await db.select().from(assignmentSubmissions).where(and(eq(assignmentSubmissions.assignmentId, input.assignmentId), eq(assignmentSubmissions.studentId, input.studentId))).orderBy(desc(assignmentSubmissions.submittedAt)).limit(1); return result[0]; }
export async function listOwnedAssignmentSubmissions(assignmentId: number, teacherId: number) { const db = await getDb(); if (!db) return []; const assignment = await db.select({ id: assignments.id }).from(assignments).where(and(eq(assignments.id, assignmentId), eq(assignments.createdBy, teacherId))).limit(1); if (!assignment[0]) return null; return listAssignmentSubmissions(assignmentId); }
export async function gradeOwnedAssignmentSubmission(id: number, teacherId: number, input: { score: number; feedback?: string }) { const db = await getDb(); if (!db) throw new Error("Database unavailable"); const rows = await db.select({ submission: assignmentSubmissions, ownerId: assignments.createdBy }).from(assignmentSubmissions).innerJoin(assignments, eq(assignmentSubmissions.assignmentId, assignments.id)).where(eq(assignmentSubmissions.id, id)).limit(1); if (!rows[0] || rows[0].ownerId !== teacherId) return null; return gradeAssignmentSubmission(id, input); }
